class CUDAMFTKernelModule(MFTSpecial):
    """CUDA PTX target used for direct Python kernel launches."""

    def __init__(
        self,
        name,
        *,
        source,
        dependencies=None,
        compiler=None,
        flags=None,
        silent=None,
        configuration=None,
    ):
        dependencies = [source, *(dependencies or [])]
        super().__init__(name, dependencies=dependencies, silent=silent)
        self._configuration = (
            Configuration.for_backend("cuda")
            if configuration is None
            else configuration.clone()
        )
        if compiler is None:
            compiler = self._configuration.get_nested(
                "executables", "compiler", default="nvcc"
            )
        self._compiler = compiler
        self._flags = [
            *self._configuration.get_nested("flags", "ptx", default=["-ptx"]),
            *(flags or []),
            *self._configuration.get_nested("flags", "extra_ptx", default=[]),
        ]

    def generate(self, *flags):
        summary = self.get_dependency_summary()
        direct_dependencies = list(self.dependencies)
        if not direct_dependencies:
            raise ValueError(
                f"{type(self).__name__} expects one direct source dependency."
            )
        source_files = list(
            direct_dependencies[0].get_compile_input_contributions()
        )
        if len(source_files) != 1:
            raise ValueError(
                f"{type(self).__name__} expects exactly one compile input."
            )
        cmd_flags = [
            *self._flags,
            *flags,
            *summary["compile_flags"],
            self._join_flags(
                self._configuration.get_nested(
                    "prefixes", "include", default="-I"
                ),
                summary["include_dirs"],
            ),
        ]
        cmd_flags = " ".join(flag for flag in cmd_flags if flag)
        yield (
            f"{self._compiler} {source_files[0]} -o {self.target_name()}"
            + (f" {cmd_flags}" if cmd_flags else "")
        )


