class CUDAKernelRequest(KernelRequest):
    """Base request object describing a CUDA kernel launch parameter."""

    _id = ""

    def __init__(self, num, sym):
        self._num = num
        self._sym = sym
        super().__init__(
            descriptor=f"{type(self).__name__}_{sym}_{num}",
            max_value=num,
            min_value=0,
            source=None,
        )

    def expr(self):
        return f"{type(self).cuda_namespace}.{self._sym}"

    @property
    def cuda_namespace(self):
        return type(self).cuda_namespace

    @property
    def launch_extent(self):
        return self._num

    @property
    def launch_axis(self):
        return self._sym

    @property
    def launch_role(self):
        raise NotImplementedError("must be implemented in subclass")


