class CUDADeviceResource(CComputeResource):
    """Device-side CUDA compute resource."""

    DEFAULT_LOCAL_VARIABLE_CLASS = CUDALocalVariable

    def __init__(
        self,
        descriptor="DEFAULT_CUDA_DEVICE",
        sthreads=tuple("xyz"),
        nthreads=1024,
        sblocks=tuple("xyz"),
        nblocks=(1 << 32),
        outer_layer=None,
        next_layer=None,
        max_value=None,
    ):
        if max_value is None:
            max_value = nthreads
        super().__init__(
            descriptor,
            outer_layer=outer_layer,
            next_layer=next_layer,
            max_value=max_value,
        )
        self._avail_thrd_dim = nthreads
        self._avail_blck_dim = nblocks
        self._avail_thrd_sym = sthreads
        self._avail_blck_sym = sblocks
        if next_layer is not None:
            self._next_layer = next_layer

    def get_default_resource(self):
        return CComputeResource("DEFAULT", outer_layer=self)

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name, loop_container, loop_capture
        return CUDAIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def request_thread_num(self):
        return self._avail_thrd_dim

    def request_block_num(self):
        return self._avail_blck_dim

    def request_mfe_container(
        self,
        variable,
        *,
        name=None,
        local_variable_capture=None,
        loop_capture=None,
        context,
    ):
        # Splitting only makes progress when the inner resource can cover more
        # than one index. With ``max_value == 1`` the generic split logic would
        # recreate the same outer selector indefinitely.
        if variable.max_value > self._max_value and self._max_value > 1:
            first, second = variable.split(self._max_value)

            if loop_capture is None:
                return None

            # this will trigger the loop handling of these two first, and that might split them again.
            loop_capture.requires(second)
            loop_capture.requires(first)

            mfe_container = self.create_combine_container(
                first,
                second,
                context=context,
                local_variable_capture=local_variable_capture,
            )
            reduced = self

        else:
            request, reduced = self.exhaust(variable)
            if reduced is None:
                if variable.max_value > self._max_value and self._max_value <= 1:
                    return self.peel_layer(), None
                return super().request_mfe_container(
                    variable,
                    name=name,
                    local_variable_capture=local_variable_capture,
                    loop_capture=loop_capture,
                    context=context,
                )

            mfe_container = self.create_mfe_container(
                context=context,
                local_variable_capture=local_variable_capture,
                loop_capture=loop_capture,
            )

            mfe_container.assign_request_parameters(
                request,
                local_variable_capture=local_variable_capture,
                local_variable_class=type(self).DEFAULT_LOCAL_VARIABLE_CLASS,
            )

        # if the resource cannot handle it, push to outer scope
        if mfe_container is None:
            return self, None

        # prime the output variable
        mfe_container.assign_multiframe_variable(
            variable,
            name=name,
            local_variable_class=type(self).DEFAULT_LOCAL_VARIABLE_CLASS,
        )
        return reduced, mfe_container

    def exhaust(self, variable):
        num = variable.max_value

        if len(self._avail_thrd_sym) > 0 and num <= self._avail_thrd_dim:
            sym, *remaining_sym = self._avail_thrd_sym
            remaining_dim = self._avail_thrd_dim // num

            max_value = remaining_dim
            if remaining_dim < 32:
                remaining_dim = 0
                max_value = self._avail_blck_dim

            reduced = CUDADeviceResource(
                self._descriptor + f"-T{sym}{num}",
                sthreads=tuple(remaining_sym),
                nthreads=remaining_dim,
                sblocks=self._avail_blck_sym,
                nblocks=self._avail_blck_dim,
                outer_layer=None,
                next_layer=self._next_layer,
                max_value=max_value,
            )
            return CUDAKernelThreadRequest(num, sym), reduced

        if len(self._avail_blck_sym) > 0 and num <= self._avail_blck_dim:
            sym, *remaining_sym = self._avail_blck_sym
            remaining_dim = self._avail_blck_dim // num

            reduced = CUDADeviceResource(
                self._descriptor + f"-B{sym}{num}",
                sthreads="",
                nthreads=0,
                sblocks=tuple(remaining_sym),
                nblocks=remaining_dim,
                outer_layer=None,
                next_layer=self._next_layer,
                max_value=remaining_dim,
            )
            return CUDAKernelBlockRequest(num, sym), reduced

        return None, None

    def create_mfe_container(
        self,
        *,
        name=None,
        local_variable_capture=None,
        loop_container=None,
        loop_capture=None,
        context,
    ):
        container = CUDAMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
            loop_capture=loop_capture,
        )
        return container


class CUDARoutineCallContainer(CRoutineCallContainer):
    """CUDA routine call using launch brackets for kernels."""

    @staticmethod
    def _format_dim3(extents):
        ordered = [max(1, int(extents[axis])) for axis in ("x", "y", "z")]
        while len(ordered) > 1 and ordered[-1] == 1:
            ordered.pop()
        if len(ordered) == 1:
            return str(ordered[0])
        return f"dim3({', '.join(map(str, ordered))})"

    def get_launch_configuration(self):
        block_extents = {"x": 1, "y": 1, "z": 1}
        grid_extents = {"x": 1, "y": 1, "z": 1}
        imported_container = self._imp_routine.imported.container
        if imported_container is None:
            return "1, 1"
        for variable in imported_container.get_kernel_variables():
            axis = getattr(variable, "launch_axis", "x")
            extent = variable.launch_extent
            if isinstance(variable, CUDAKernelThreadRequest):
                block_extents[axis] = max(block_extents[axis], extent)
            elif isinstance(variable, CUDAKernelBlockRequest):
                grid_extents[axis] = max(grid_extents[axis], extent)
        return (
            f"{self._format_dim3(grid_extents)}, "
            f"{self._format_dim3(block_extents)}"
        )

    def get_call_string(self):
        args_string = ", ".join(self.get_args_list())
        if not self._imp_routine.imported.is_kernel:
            return f"{self.get_call_name()}({args_string});"
        launch_configuration = self.get_launch_configuration()
        return f"{self.get_call_name()}<<<{launch_configuration}>>>({args_string});"


class CUDARoutineContainer(CRoutineContainer):
    """CUDA routine container with kernel qualifiers."""

    INPUT_VARIABLE_CLASS = CUDAInputVariable
    KERNEL_REQUEST_CLASS = CUDAKernelRequest

    def __init__(self, *args, **kwargs):
        self._ker_layer = None
        super().__init__(*args, **kwargs)

    def prepare_hidden_layers(self, **buildargs):
        self._context_main_ptr = super().prepare_hidden_layers(**buildargs)
        self._ker_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        return self._context_main_ptr

    def configure_container(self, **buildargs):
        # treat special mfs. What passes this layer is traditional call arg
        self._ker_layer.add_capture_trigger(KernelRequest)
        return super().configure_container(**buildargs)

    @property
    def is_kernel(self):
        return any(True for _ in self.get_kernel_variables())

    def get_kernel_variables(self, **_):
        for variable in self._ker_layer.captured:
            if isinstance(variable, KernelRequest):
                yield variable

    def get_argument_variables(self, **_):
        for variable in sorted(self._arg_layer.captured):
            if isinstance(variable, type(self).KERNEL_REQUEST_CLASS):
                continue
            yield variable

    def prepare_call_arguments(self):
        self._call_args = []
        num = 0
        for variable in self._arg_layer.captured:
            if isinstance(variable, KernelRequest):
                continue
            if isinstance(variable, LibRoutineMultiFrame):
                name = f"krnl_{num:02d}"
                num += 1
                loc = variable.create_input_representative(
                    context=self.context,
                    dtype="i32",
                    size=None,
                    name=name,
                    input_variable_class=type(self).INPUT_VARIABLE_CLASS,
                    autorequire=False,
                )
                self._ios_layer.requires(loc)
            else:
                self._ios_layer.requires(variable)
            self._call_args.append(variable)

    def get_signature(self, *, terminate=False):
        signature = super().get_signature(terminate=terminate)
        if self.is_kernel:
            signature = f"__global__ {signature}"
        return f'extern "C" {signature}'


