class CUDABuilder(CBuilder, identifier="CUDA"):
    """CUDA builder using the C lowering plus kernel-aware multiframe handling."""

    _assignment_class = CAssignmentStatementLine

    def create_libroutine_variable(
        self,
        *,
        name,
        dtype,
        status,
        size,
        assignment=None,
        namespace=None,
        **kwargs,
    ):
        if status & LibRoutineVariable.STATUS_BUFFER:
            return CUDABufferVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        status = status & 3
        if status == CUDAInputVariable.STATUS_INPUT:
            return CUDAInputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == CUDAOutputVariable.STATUS_OUTPUT:
            return CUDAOutputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == CUDAInOutVariable.STATUS_INOUT:
            return CUDAInOutVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        return super().create_libroutine_variable(
            name=name,
            dtype=dtype,
            status=status,
            size=size,
            assignment=assignment,
            namespace=namespace,
            **kwargs,
        )

    def as_numeric(self, variable):
        return CNumeric(variable)

    def create_external_array(self, *args, context, **kwargs):
        return Builder.create_external_array(
            self,
            *args,
            context=context,
            local_class=CUDALocalVariable,
            constant_class=CUDAConstant,
        )


class CUDALibRoutine(CLibRoutine):
    """CUDA lib routine."""

    def __init__(self, *args, is_kernel=False, **kwargs):
        super().__init__(*args, **kwargs)
        self._explicit_is_kernel = bool(is_kernel)

    @property
    def is_kernel(self):
        container = self.container
        return bool(
            self._explicit_is_kernel
            or (container is not None and getattr(container, "is_kernel", False))
        )


class CUDALibrary(CLibrary):
    """CUDA source and header emission."""

    BACKEND_IDENTIFIER = "cuda"
    FILEENDING = "cu"
    LIBROUTINE_CLASS = CUDALibRoutine
    IMPORTLINE_CLASS = CUDAImportContainer
    DEFAULT_BUILDER = CUDABuilder
    DEFAULT_CONTAINER_CLASS = CUDARoutineContainer

    def __init__(
        self,
        plain_name,
        build_hash=None,
        resource=None,
        configuration=None,
        general_configuration=None,
    ):
        if resource is None:
            resource = CUDAHostResource("DefaultCUDAResource")
        super().__init__(
            plain_name,
            build_hash=build_hash,
            resource=resource,
            configuration=configuration,
            general_configuration=general_configuration,
        )

    @property
    def headername(self):
        return self._get_headername()

    def _get_headername(self):
        return f"{self.libname}.cuh"

    @property
    def kernelmodulename(self):
        return self._get_kernelmodulename()

    def _get_kernelmodulename(self):
        return f"{self.libname}.ptx"

    @property
    def kernelbuildname(self):
        return self._get_kernelbuildname()

    def _get_kernelbuildname(self):
        return f"build_{self.libname}_cuda"

    def has_kernel_routines(self):
        return any(
            libroutine.is_kernel for _, libroutine in self.content
        )

    def get_manifest_payload(self):
        payload = super().get_manifest_payload()
        for routine_entry, (_name, libroutine) in zip(
            payload["compatibility"]["routines"], self.content, strict=True
        ):
            routine_entry["kernel"] = bool(libroutine.is_kernel)
        return payload

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(f'#include "{self.libname}.cuh"')

    def generate_prmb_containers(self, **_):
        imports = list(self.import_capture.list_imports())
        if imports:
            yield from self.codelines_from_text("")
            for library, routines in imports:
                yield CUDAImportContainer(
                    library, routines, context=self.context
                )

        constants = list(self.definition_capture.captured)
        if constants:
            yield from self.codelines_from_text("")
            for variable in constants:
                for line in variable.get_definition_lines():
                    yield from self.codelines_from_text(line)

        yield from self.codelines_from_text("")
        for dtype, ctype, zero_value in (
            ("f64", "double", "0.0"),
            ("f32", "float", "0.0f"),
            ("i64", "int64_t", "0"),
            ("i32", "int32_t", "0"),
        ):
            yield from self.codelines_from_text(
                f"__host__ __device__ static inline void phoenix_zero_{dtype}({ctype} *buffer, int32_t size) {{"
            )
            yield from self.codelines_from_text(
                "    for (int32_t idx = 0; idx < size; ++idx) {"
            )
            yield from self.codelines_from_text(
                f"        buffer[idx] = {zero_value};"
            )
            yield from self.codelines_from_text("    }")
            yield from self.codelines_from_text("}")
            yield from self.codelines_from_text("")

    def get_support_target(self):
        selected_adaa = str(
            self.backend_configuration.get_nested(
                "runtime", "adaa_library", default="cupy"
            )
        ).strip().lower()
        if selected_adaa != "pycuda":
            return None
        support_makefile = self.backend_configuration.get_nested(
            "support", "makefile", default=None
        )
        support_root = self.backend_configuration.get_nested(
            "support", "root", default=None
        )
        build_target = self.backend_configuration.get_nested(
            "support", "build_target", default=None
        )
        support_library = self.backend_configuration.get_nested(
            "support", "library_file", default=None
        )
        if not support_makefile or not support_root or not build_target:
            return None
        required = [support_library] if support_library else []
        return BackendSupportBuildTarget(
            f"support_{self.libname}_{type(self).BACKEND_IDENTIFIER}",
            support_root=support_root,
            makefile=support_makefile,
            build_target=build_target,
            required_files=required,
        )

    def get_object_target(self):
        dependencies = [*self.get_makefile_compile_dependency_targets()]
        return CUDAMFTObject(
            self.relative_to_basepath(self.objectname),
            source=self.get_codefile_target(),
            dependencies=[self.get_header_target(), *dependencies],
            configuration=self.backend_configuration,
        )

    def get_library_target(self):
        dependencies = [
            self.get_object_target(),
            *self.get_makefile_dependency_targets(),
        ]
        return CUDAMFTSharedLibrary(
            self.relative_to_basepath(self.sharedlibname),
            dependencies=dependencies,
            configuration=self.backend_configuration,
        )

    def get_kernel_module_target(self):
        if not self.has_kernel_routines():
            return None
        dependencies = [*self.get_makefile_compile_dependency_targets()]
        return CUDAMFTKernelModule(
            self.relative_to_basepath(self.kernelmodulename),
            source=self.get_codefile_target(),
            dependencies=[self.get_header_target(), *dependencies],
            configuration=self.backend_configuration,
        )

    def get_build_target(self):
        dependencies = [self.get_library_target()]
        kernel_target = self.get_kernel_module_target()
        if kernel_target is not None:
            dependencies.append(kernel_target)
        support_target = self.get_support_target()
        if support_target is not None:
            dependencies.append(support_target)
        return MFTPattern(
            self.relative_to_basepath(self.kernelbuildname),
            dependencies=dependencies,
        )

    def get_makefile_targets(self):
        yield self.get_codefile_target()
        yield self.get_header_target()
        yield self.get_object_target()
        yield self.get_library_target()
        kernel_target = self.get_kernel_module_target()
        if kernel_target is not None:
            yield kernel_target
        yield self.get_build_target()

    def get_execution_target(self):
        return self.get_build_target()

    def get_compilation_output_files(self):
        yield self.sharedlibname
        if self.has_kernel_routines():
            yield self.kernelmodulename


CUDABuilder.set_instruction_class_handler(
    AffineOperationInstruction, CUDABuilder.handle_affine_instruction
)
CUDABuilder.set_instruction_class_handler(
    BiLinearOperationInstruction, CUDABuilder.handle_bilinear_instruction
)

CUDARoutineContainer.set_comment_class(CUDACommentLine)

CUDABuilder.set_comment_class(CUDACommentLine)
CUDABuilder.set_routinecall_class(CUDARoutineCallContainer)
register_cuda_atomic_handlers(CUDABuilder)
